const express = require("express");
const cors = require("cors");
const bcrypt = require("bcryptjs");
require("dotenv").config();
const mongoose = require("mongoose");
const jwt = require("jsonwebtoken");

const app = express();

app.use(cors());
app.use(express.json());

// ==========================================
// VERSION 6M - USER PROFILE FIELDS
// ==========================================

const userSchema = new mongoose.Schema({

  name: {
      type: String,
          required: true,
            },

              email: {
                  type: String,
                      required: true,
                          unique: true,
                            },

                              password: {
                                  type: String,
                                      required: true,
                                        },

                                          college: {
                                              type: String,
                                                  default: "",
                                                    },

                                                      degree: {
                                                          type: String,
                                                              default: "",
                                                                },

                                                                  year: {
                                                                      type: String,
                                                                          default: "",
                                                                            },

                                                                              goal: {
                                                                                  type: String,
                                                                                      default: "",
                                                                                        },

                                                                                        });

                                        const User = mongoose.model("User", userSchema);

                                        // ==========================================
                                        // VERSION 6I - JWT AUTHENTICATION MIDDLEWARE
                                        // ==========================================

                                        function authenticateToken(req, res, next) {

                                          const authHeader = req.headers["authorization"];

                                            const token = authHeader && authHeader.split(" ")[1];

                                              if (!token) {

                                                  return res.status(401).json({
                                                        success: false,
                                                              message: "Access denied. Please login.",
                                                                  });

                                                                    }

                                                                      jwt.verify(
                                                                          token,
                                                                              process.env.JWT_SECRET,
                                                                                  (error, user) => {

                                                                                        if (error) {

                                                                                                return res.status(403).json({
                                                                                                          success: false,
                                                                                                                    message: "Invalid or expired token.",
                                                                                                                            });

                                                                                                                                  }

                                                                                                                                        req.user = user;

                                                                                                                                              next();
                                                                                                                                                  }
                                                                                                                                                    );
                                                                                                                                                    }

                                                                                                                                                    // ==========================================
                                                                                                                                                    // VERSION 6I - PROTECTED USER API
                                                                                                                                                    // ==========================================

                                                                                                                                                    app.get("/api/profile", authenticateToken, async (req, res) => {

                                                                                                                                                      try {

                                                                                                                                                          const user = await User.findById(req.user.id)
                                                                                                                                                                .select("-password");

                                                                                                                                                                    if (!user) {

                                                                                                                                                                          return res.status(404).json({
                                                                                                                                                                                  success: false,
                                                                                                                                                                                          message: "User not found.",
                                                                                                                                                                                                });

                                                                                                                                                                                                    }

                                                                                                                                                                                                        res.json({
                                                                                                                                                                                                              success: true,
                                                                                                                                                                                                                    user: user,
                                                                                                                                                                                                                        });

                                                                                                                                                                                                                          } catch (error) {

                                                                                                                                                                                                                              console.error(error);

                                                                                                                                                                                                                                  res.status(500).json({
                                                                                                                                                                                                                                        success: false,
                                                                                                                                                                                                                                              message: "Server error.",
                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                    // ==========================================
                                                                                                                                                                                                                                                    // VERSION 6L - UPDATE USER PROFILE
                                                                                                                                                                                                                                                    // ==========================================

                                                                                                                                                                                                                                                    app.put("/api/profile", authenticateToken, async (req, res) => {

                                                                                                                                                                                                                                                      try {

                                                                                                                                                                                                                                                          const { name, college, degree, year, goal } = req.body;

                                                                                                                                                                                                                                                              const user = await User.findById(req.user.id);

                                                                                                                                                                                                                                                                  if (!user) {

                                                                                                                                                                                                                                                                        return res.status(404).json({
                                                                                                                                                                                                                                                                                success: false,
                                                                                                                                                                                                                                                                                        message: "User not found."
                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                      // Update profile fields
                                                                                                                                                                                                                                                                                                          if (name !== undefined) {
                                                                                                                                                                                                                                                                                                                user.name = name;
                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                        if (college !== undefined) {
                                                                                                                                                                                                                                                                                                                              user.college = college;
                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                      if (degree !== undefined) {
                                                                                                                                                                                                                                                                                                                                            user.degree = degree;
                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                    if (year !== undefined) {
                                                                                                                                                                                                                                                                                                                                                          user.year = year;
                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                  if (goal !== undefined) {
                                                                                                                                                                                                                                                                                                                                                                        user.goal = goal;
                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                await user.save();

                                                                                                                                                                                                                                                                                                                                                                                    res.json({
                                                                                                                                                                                                                                                                                                                                                                                          success: true,
                                                                                                                                                                                                                                                                                                                                                                                                message: "Profile updated successfully! 🎉",
                                                                                                                                                                                                                                                                                                                                                                                                      user: {
                                                                                                                                                                                                                                                                                                                                                                                                              id: user._id,
                                                                                                                                                                                                                                                                                                                                                                                                                      name: user.name,
                                                                                                                                                                                                                                                                                                                                                                                                                              email: user.email,
                                                                                                                                                                                                                                                                                                                                                                                                                                      college: user.college,
                                                                                                                                                                                                                                                                                                                                                                                                                                              degree: user.degree,
                                                                                                                                                                                                                                                                                                                                                                                                                                                      year: user.year,
                                                                                                                                                                                                                                                                                                                                                                                                                                                              goal: user.goal
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } catch (error) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.error("Profile update error:", error);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  res.status(500).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              message: "Server error."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });


const PORT = 3000;

mongoose
  .connect(process.env.MONGODB_URI)
    .then(() => {
        console.log("MongoDB connected successfully!");
          })
            .catch((error) => {
                console.error("MongoDB connection failed:", error);
                  });

// Middleware
app.use(cors());
app.use(express.json());

// Serve frontend files
app.use(express.static(__dirname));



// Home page
app.get("/", (req, res) => {
    res.sendFile(__dirname + "/index.html");
    });


    // Health check
    app.get("/api/health", (req, res) => {
        res.json({
                success: true,
                        message: "Placement Tracker backend is running 🚀"
                            });
                            });


                            // REGISTER API
                            app.post("/api/register", async (req, res) => {

                                try {

                                        const { name, email, password } = req.body;

                                                if (!name || !email || !password) {
                                                            return res.status(400).json({
                                                                            success: false,
                                                                                            message: "Name, email and password are required."
                                                                                                        });
                                                                                                                }

                                                                                                                        if (password.length < 6) {
                                                                                                                                    return res.status(400).json({
                                                                                                                                                    success: false,
                                                                                                                                                                    message: "Password must contain at least 6 characters."
                                                                                                                                                                                });
                                                                                                                                                                                        }

                                                                                                                                                                                                const existingUser = await User.findOne({
                                                                                                                                                                                                          email: email.toLowerCase(),
                                                                                                                                                                                                          });
                                                                                                                                                                                                        
                                                                                                                                                                                                                if (existingUser){

                                                                                                                                                                                                                     return res.status(409).json({
                                                                                                                                                                                                                        
                                                                                                                                                                                                                        success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                message: "Email is already registered."
                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                    const hashedPassword =
                                                                                                                                                                                                                                                                                                                await bcrypt.hash(password, 10);

                                                                                                                                                                                                                                                                                                                                                                                        const newUser = new User({
                                                                                                                                                                                                                                                                                                                                                                                                  name: name,
                                                                                                                                                                                                                                                                                                                                                                                                    email: email.toLowerCase(),
                                                                                                                                                                                                                                                                                                                                                                                                      password: hashedPassword,
                                                                                                                                                                                                                                                                                                                                                                                                      });

                                                                                                                                                                                                                                                                                                                                                                                                      await newUser.save();
                                                                                                                                                                                                                                                                                                                                                                                        

                                                                                                                                                                                                                                                                                                                                                                                                       res.status(201).json({
                                                                                                                                                                                                                                                                                                                                                                                                            success: true,
                                                                                                                                                                                                                                                                                                                                                                                                                        message: "Account created successfully! 🎉",
                                                                                                                                                                                                                                                                                                                                                                                                                                    user: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    id: newUser.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    name: newUser.name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    email: newUser.email
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (error) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.error(error);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            res.status(500).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    message: "Server error."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // VERSION 6C - LOGIN API
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                app.post("/api/login", async (req, res) => {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    try {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const { email, password } = req.body;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Validate input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!email || !password) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return res.status(400).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        message: "Email and password are required."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Find user
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const user = await User.findOne({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  email: email.toLowerCase(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // User not found
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!user) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return res.status(401).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            message: "Invalid email or password."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Check password
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const passwordMatch =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await bcrypt.compare(password, user.password);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!passwordMatch) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return res.status(401).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                message: "Invalid email or password."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // VERSION 6I - CREATE JWT TOKEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ==========================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const token = jwt.sign(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  id: user._id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      email: user.email,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          process.env.JWT_SECRET,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                expiresIn: "7d",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  res.json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    success: true,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      message: "Login successful! 🎉",

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        token: token,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          user: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              id: user._id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  name: user.name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      email: user.email,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    catch (error) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.error(error);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    res.status(500).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            message: "Server error."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Start server
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                app.listen(PORT, () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log(`Server running on port ${PORT}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });